        heading: "Что это и зачем",
        text: `<strong>Что это:</strong> партнерский сервис - внешняя система, которая подключена к платформе по API (open banking) и работает с клиентами банка. Например, сторонний кошелек или финтех-приложение.<br>
<strong>Зачем раздел:</strong> здесь заводятся такие сервисы, выбирается режим авторизации, задаются права, каналы и вебхуки, видно, какие клиенты пришли через сервис и в каком статусе подключение. Все изменения защищены подтверждением 2FA.<br>
<strong>Два режима авторизации:</strong> FULL_OAUTH - полная авторизация по OAuth, LIGHT - лёгкий режим, клиент банка проходит регистрацию и KYC на стороне банка.`,
